      sketch: {
        title: "t",
        goalSummary: "g",
        novice: false,
        milestones: ["Data explored", "First model trained"],
        conceptRadar: [{ concept: "data leakage", whyItMatters: "inflates metrics", likelyMomentType: "spot_issue" }],
